.section-title {
  font-family: 'Georgia', serif;
  font-size: 28px;
  color: #343a40;
  position: relative;
  padding-bottom: 10px;
  margin-bottom: 20px;
}

.section-title::after {
  content: '';
  display: block;
  width: 60px;
  height: 3px;
  background-color: #007bff;
  position: absolute;
  bottom: 0px;
  left: 0px;
  background-image: linear-gradient(to right, #007bff, #0056b3);
  border-radius: 2px;
  box-shadow: 0px 1px 3px rgba(0, 0, 0, 0.2);
  transition: width 0.3s ease-in-out;
}

.section-title:hover::after {
  width: 100px;
  background-color: #0056b3;
  box-shadow: 0px 2px 5px rgba(0, 0, 0, 0.3);
}

.section-title::before {
  content: "—";
  position: absolute;
  top: 5px;
  left: -20px;
  color: #6c757d;
  font-size: 20px;
}

